import asyncioimport hashlibimport hmacimport jsonimport loggingimport osimport timeimport requestsimport websocketsfrom market_data import (    MarketDataStore,    OrderBookStore,    SymbolRanker,    TradeStore,    OrderFlowAnalyzer,    LiquidityEngine,    SignalGenerator,    SignalConfig,    PaperTradingEngine,)logging.basicConfig(    level=logging.INFO,    format="%(message)s",    handlers=[logging.FileHandler("bitmart_futures.log"), logging.StreamHandler()],)log = logging.getLogger()logging.getLogger("httpx").setLevel(logging.WARNING)logging.getLogger("httpcore").setLevel(logging.WARNING)DEMO_TRADING = TruePROD_PUBLIC_WS = "wss://openapi-ws-v2.bitmart.com/api?protocol=1.1"PROD_PRIVATE_WS = "wss://openapi-ws-v2.bitmart.com/user?protocol=1.1"DEMO_PUBLIC_WS = "wss://openapi-wsdemo-v2.bitmart.com/api?protocol=1.1"DEMO_PRIVATE_WS = "wss://openapi-wsdemo-v2.bitmart.com/user?protocol=1.1"PUBLIC_WS_URL = DEMO_PUBLIC_WS if DEMO_TRADING else PROD_PUBLIC_WSPRIVATE_WS_URL = DEMO_PRIVATE_WS if DEMO_TRADING else PROD_PRIVATE_WSPING_INTERVAL_SEC = 15RECONNECT_BASE_DELAY_SEC = 3RECONNECT_MAX_DELAY_SEC = 60HEARTBEAT_INTERVAL_SEC = 30TICKER_CHANNEL = "futures/ticker"DEPTH_LEVELS = 20DEPTH_CHANNEL_PREFIX = f"futures/depth{DEPTH_LEVELS}:"TRADE_CHANNEL_PREFIX = "futures/trade:"WATCHLIST_TOP_N = 15WATCHLIST_WARMUP_SEC = 10WATCHLIST_INTERVAL_SEC = 30SYMBOL_STALE_AFTER_SEC = 30TRADE_WINDOWS_MS = (500, 1000, 2000, 5000)ORDER_FLOW_INTERVAL_SEC = 0.1SIGNAL_INTERVAL_SEC = 1.0PAPER_TAKER_FEE_RATE = 0.0006PAPER_MAX_TRADE_DURATION_SEC = 60.0class WatchlistState:    def __init__(self) -> None:        self.symbols = set()def _load_db_config() -> dict:    here = os.path.dirname(os.path.abspath(__file__))    candidates = [        os.path.join(here, "db.txt"),        os.path.join(os.path.dirname(here), "db.txt"),    ]    for path in candidates:        if os.path.exists(path):            config = {}            with open(path, "r") as f:                for line in f:                    line = line.strip()                    if not line or line.startswith("#"):                        continue                    if "=" in line:                        k, _, v = line.partition("=")                        config[k.strip()] = v.strip().strip('"')            return config    raise FileNotFoundError(f"db.txt not found in any of: {candidates}")def _clean_secret(value):    if value is None:        return None    if isinstance(value, str):        value = value.strip()        if value.upper() in ("", "NULL"):            return None    return valuedef load_bitmart_credentials() -> dict:    from supabase import create_client    config = _load_db_config()    sb = create_client(config["SUPABASE_URL"], config["SUPABASE_KEY"])    rows = sb.table("api_keys").select("*").execute()    match = next(        (r for r in rows.data or [] if (r.get("exchange_name") or "").strip().lower() == "bitmart"),        None,    )    if not match:        raise RuntimeError("No 'BitMart' row found in the api_keys Supabase table")    api_key = _clean_secret(match.get("api_key"))    api_secret = _clean_secret(match.get("api_secret"))    memo = _clean_secret(match.get("memo"))    missing = [n for n, v in (("api_key", api_key), ("api_secret", api_secret), ("memo", memo)) if not v]    if missing:        raise RuntimeError(f"BitMart credentials incomplete in Supabase — missing: {', '.join(missing)}")    return {"api_key": api_key, "api_secret": api_secret, "memo": memo}def get_outbound_ip():    try:        resp = requests.get("https://api.ipify.org?format=json", timeout=5)        return resp.json().get("ip")    except Exception:        return Nonedef build_login_sign(timestamp_ms: str, memo: str, api_secret: str) -> str:    payload = f"{timestamp_ms}#{memo}#bitmart.WebSocket"    return hmac.new(api_secret.encode(), payload.encode(), hashlib.sha256).hexdigest()async def _keepalive(ws):    while True:        await asyncio.sleep(PING_INTERVAL_SEC)        try:            await ws.send(json.dumps({"action": "ping"}))        except Exception:            returnasync def _watchlist_loop(ws, ranker: SymbolRanker, order_book: OrderBookStore, trade_store: TradeStore, watchlist_state: WatchlistState):    current = set()    await asyncio.sleep(WATCHLIST_WARMUP_SEC)    while True:        top = set(await ranker.top_symbols())        added = top - current        removed = current - top        if removed:            channels = [f"{DEPTH_CHANNEL_PREFIX}{s}" for s in removed] + [f"{TRADE_CHANNEL_PREFIX}{s}" for s in removed]            await ws.send(json.dumps({"action": "unsubscribe", "args": channels}))            for symbol in removed:                await order_book.remove(symbol)                await trade_store.remove(symbol)        if added:            channels = [f"{DEPTH_CHANNEL_PREFIX}{s}" for s in added] + [f"{TRADE_CHANNEL_PREFIX}{s}" for s in added]            await ws.send(json.dumps({"action": "subscribe", "args": channels}))        if added or removed:            current = top            watchlist_state.symbols = set(current)            log.info(f"[watchlist] now tracking {sorted(current)}")        await asyncio.sleep(WATCHLIST_INTERVAL_SEC)async def run_public(market_data: MarketDataStore, order_book: OrderBookStore, ranker: SymbolRanker, trade_store: TradeStore, watchlist_state: WatchlistState):    delay = RECONNECT_BASE_DELAY_SEC    while True:        try:            log.info(f"[public] connecting to {PUBLIC_WS_URL}")            async with websockets.connect(PUBLIC_WS_URL, ping_interval=None) as ws:                log.info("[public] connected")                delay = RECONNECT_BASE_DELAY_SEC                await ws.send(json.dumps({"action": "subscribe", "args": [TICKER_CHANNEL]}))                keepalive_task = asyncio.create_task(_keepalive(ws))                watchlist_task = asyncio.create_task(_watchlist_loop(ws, ranker, order_book, trade_store, watchlist_state))                try:                    async for raw in ws:                        if raw == "pong":                            continue                        try:                            msg = json.loads(raw)                        except json.JSONDecodeError:                            log.warning(f"[public] non-JSON message: {raw[:200]}")                            continue                        group = msg.get("group", "")                        action = msg.get("action")                        if action == "subscribe":                            if msg.get("success"):                                log.info(f"[public] \u2705 subscribed to {msg.get('group')}")                            else:                                log.error(f"[public] \u274c subscribe failed: {msg}")                        elif action == "unsubscribe":                            if not msg.get("success"):                                log.error(f"[public] \u274c unsubscribe failed: {msg}")                        elif group == TICKER_CHANNEL:                            data = msg.get("data") or {}                            await market_data.update_from_ticker(data)                            await ranker.update_from_ticker(data)                        elif group.startswith(DEPTH_CHANNEL_PREFIX):                            await order_book.apply_depth_update(msg.get("data") or {})                        elif group.startswith(TRADE_CHANNEL_PREFIX):                            data = msg.get("data")                            if isinstance(data, list):                                for item in data:                                    await trade_store.apply_trade(item)                            elif isinstance(data, dict):                                await trade_store.apply_trade(data)                finally:                    keepalive_task.cancel()                    watchlist_task.cancel()        except Exception as e:            log.error(f"[public] connection error: {type(e).__name__}: {str(e)[:200]} \u2014 reconnecting in {delay}s")            await asyncio.sleep(delay)            delay = min(delay * 2, RECONNECT_MAX_DELAY_SEC)async def run_heartbeat(market_data: MarketDataStore, order_book: OrderBookStore):    while True:        await asyncio.sleep(HEARTBEAT_INTERVAL_SEC)        symbol_count = await market_data.symbol_count()        book_count = len(await order_book.symbols())        log.info(f"[heartbeat] tracking {symbol_count} tickers, {book_count} order books")async def run_order_flow(order_flow: OrderFlowAnalyzer, watchlist_state: WatchlistState):    while True:        await asyncio.sleep(ORDER_FLOW_INTERVAL_SEC)        symbols = list(watchlist_state.symbols)        if symbols:            await order_flow.recompute(symbols)def _log_signal(signal):    log.info(        f"[signal] {signal.direction.upper()} {signal.symbol} "        f"confidence={signal.confidence:.2f} entry={signal.entry_price} "        f"tp={signal.take_profit:.6f} sl={signal.stop_loss:.6f} "        f"reasons={signal.reasons}"    )def _log_trade_result(result):    log.info(        f"[paper] {result.symbol} {result.direction} closed {result.outcome} "        f"entry={result.entry_price} exit={result.exit_price} "        f"duration={result.duration_sec:.1f}s mfe={result.mfe_pct:.4%} mae={result.mae_pct:.4%} "        f"gross={result.gross_profit_pct:.4%} fees={result.fees_pct:.4%} net={result.net_profit_pct:.4%}"    )def _log_paper_stats(stats: dict):    log.info(        f"[paper-stats] signals={stats['total_signals']} wins={stats['winning_trades']} "        f"losses={stats['losing_trades']} win_rate={stats['win_rate']:.2%} "        f"avg_profit={stats['average_profit_pct']:.4%} avg_loss={stats['average_loss_pct']:.4%} "        f"profit_factor={stats['profit_factor']:.2f} net_pnl={stats['net_pnl_pct']:.4%} "        f"avg_hold={stats['average_holding_time_sec']:.1f}s"    )async def run_trading_loop(    market_data: MarketDataStore,    signal_generator: SignalGenerator,    paper_engine: PaperTradingEngine,    watchlist_state: WatchlistState,):    while True:        await asyncio.sleep(SIGNAL_INTERVAL_SEC)        now = time.time()        for symbol in list(watchlist_state.symbols):            market = await market_data.get(symbol)            if not market:                continue            if await paper_engine.has_open_trade(symbol):                result = await paper_engine.update(symbol, market["last_price"], now)                if result:                    _log_trade_result(result)                    _log_paper_stats(await paper_engine.stats())                continue            signal = await signal_generator.evaluate(symbol)            if signal:                _log_signal(signal)                await paper_engine.open_trade(signal)async def run_private(creds: dict):    delay = RECONNECT_BASE_DELAY_SEC    memo = creds["memo"]    while True:        try:            log.info(f"[private] connecting to {PRIVATE_WS_URL}")            async with websockets.connect(PRIVATE_WS_URL, ping_interval=None) as ws:                log.info("[private] connected \u2014 logging in")                delay = RECONNECT_BASE_DELAY_SEC                timestamp_ms = str(int(time.time() * 1000))                sign = build_login_sign(timestamp_ms, memo, creds["api_secret"])                login_msg = {"action": "access", "args": [creds["api_key"], timestamp_ms, sign, "web"]}                await ws.send(json.dumps(login_msg))                keepalive_task = asyncio.create_task(_keepalive(ws))                try:                    async for raw in ws:                        if raw == "pong":                            continue                        try:                            msg = json.loads(raw)                        except json.JSONDecodeError:                            log.warning(f"[private] non-JSON message: {raw[:200]}")                            continue                        if msg.get("action") == "access":                            if msg.get("success"):                                log.info("[private] \u2705 login successful")                            else:                                log.error(f"[private] \u274c login failed: {msg}")                                log.error("[private] if this key requires IP whitelisting, confirm this machine's outbound IP is whitelisted on BitMart")                                await asyncio.sleep(RECONNECT_MAX_DELAY_SEC)                        elif msg.get("group") == "System":                            continue                        else:                            log.info(f"[private] message: {msg}")                finally:                    keepalive_task.cancel()        except Exception as e:            log.error(f"[private] connection error: {type(e).__name__}: {str(e)[:200]} \u2014 reconnecting in {delay}s")            await asyncio.sleep(delay)            delay = min(delay * 2, RECONNECT_MAX_DELAY_SEC)async def main():    creds = load_bitmart_credentials()    outbound_ip = get_outbound_ip()    log.info(f"Outbound IP for this machine: {outbound_ip or 'could not determine'}")    log.info(f"Starting BitMart Futures bot (demo_trading={DEMO_TRADING})")    market_data = MarketDataStore()    order_book = OrderBookStore(depth_levels=DEPTH_LEVELS)    ranker = SymbolRanker(top_n=WATCHLIST_TOP_N, stale_after_sec=SYMBOL_STALE_AFTER_SEC)    trade_store = TradeStore(windows_ms=TRADE_WINDOWS_MS)    order_flow = OrderFlowAnalyzer(trade_store, windows_ms=TRADE_WINDOWS_MS)    liquidity_engine = LiquidityEngine(order_book)    signal_generator = SignalGenerator(market_data, order_flow, liquidity_engine, SignalConfig())    paper_engine = PaperTradingEngine(taker_fee_rate=PAPER_TAKER_FEE_RATE, max_trade_duration_sec=PAPER_MAX_TRADE_DURATION_SEC)    watchlist_state = WatchlistState()    await asyncio.gather(        run_public(market_data, order_book, ranker, trade_store, watchlist_state),        run_private(creds),        run_heartbeat(market_data, order_book),        run_order_flow(order_flow, watchlist_state),        run_trading_loop(market_data, signal_generator, paper_engine, watchlist_state),    )if __name__ == "__main__":    try:        asyncio.run(main())    except KeyboardInterrupt:        log.info("bitmart_futures.py stopped.")